// Links of the built guide to other sites answer (`just docs-links`; not in CI,
// other sites come and go). Run `npm run build` first.
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join, resolve } from 'node:path'

const out = resolve(new URL('..', import.meta.url).pathname, process.env.DOCS_OUT ?? '.vitepress/dist')
// Edit links are generated by the theme (one per page) and rate limited by GitHub.
const skip = /^https?:\/\/(localhost|127\.0\.0\.1|example\.(com|org))[:/]|\/edit\/main\/docs\/guide\//
const urls = new Map()
function walk(dir) {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name)
    if (statSync(path).isDirectory()) walk(path)
    else if (name.endsWith('.html'))
      for (const [, url] of readFileSync(path, 'utf8').matchAll(/<a\b[^>]*\shref="(https?:\/\/[^"#]+)/g))
        if (!skip.test(url)) urls.set(url, [...(urls.get(url) ?? []), path.slice(out.length + 1)])
  }
}
walk(out)
const failures = []
const queue = [...urls.keys()]
async function worker() {
  for (let url; (url = queue.shift()); ) {
    try {
      const res = await fetch(url, { redirect: 'follow', signal: AbortSignal.timeout(15000) })
      if (res.status >= 400) failures.push(`${res.status} ${url} (${urls.get(url)[0]})`)
    } catch (e) {
      failures.push(`${e.cause?.code ?? e.name} ${url} (${urls.get(url)[0]})`)
    }
  }
}
await Promise.all(Array.from({ length: 6 }, worker))
console.log(`${urls.size} external links, ${failures.length} failing`)
if (failures.length) {
  console.error(`  ${failures.join('\n  ')}`)
  process.exit(1)
}
